// The archive. Every entry is a historical trace of a future that did not happen.
// Positions vstg-0001 to vstg-0200. Pending entries are placeholders until they are researched.
// Each image is /public/vstg/<code>.webp (.png while it is a placeholder). Replace the file with the same name to update it.

export type Vstg = {
  code: string; // internal position, used for file names: vstg-0001
  suffix?: string; // letter when two VSTGs share a year: vstg.1922a, vstg.1922b
  year: number | null; // year the future failed. Shown as [VSTG.YYYY], or [VSTG.NA] when not confirmed
  name: string;
  image: string; // path under /public/vstg/
  description: string; // [desc.]
  failedFuture: string; // [f.f. expl.]
  source: string; // citation: author, title, publisher, year
  link: string; // where to read more
  license: string; // reuse conditions for the image
  status: string; // working state, not shown on the site
  level: "documented" | "hypothesis" | "pending"; // documented: facts sourced. hypothesis: a labelled reading. pending: not yet researched
  conceptionYear?: number | null; // year the future was imagined or planned
  closureYear?: number | null; // year it was dropped, cancelled or failed
  anchorYear?: number; // point of relation for Residual Contemporary Times (2020)
  distance?: number | null; // anchorYear minus conceptionYear, computed
  presentEffect?: {
    text: string; // how that future still shapes the present
    kind: "documented" | "attributed" | "interpretation"; // fact in a source, a named person's comment, or the author's reading
    source: string;
    link: string;
  } | null;
};

