    "image": "/vstg/vstg-0038.webp",
    "description": "Superstudio's Continuous Monument (1969): a photomontage of a monumental grid laid across the planet, where one continuous monolith covers the world.",
    "failedFuture": "An anti-architectural proposal: a single continuous monument covering the world, presented by Superstudio in 1969 as conceptual architecture. It was never built.",
    "source": "Museum of Modern Art (MoMA), \"Superstudio, Continuous Monument\" (work 938).",
    "link": "https://www.moma.org/collection/works/938",
    "license": "Image: Continuous Monument, Superstudio, 1969–70. Source: web image search. Used in a non-profit academic archive; contact to credit or remove.",
    "status": "Efecto presente atribuido a Jonathan Ringen vía Wikipedia; pendiente abrir su texto y concretar en qué obras se nota la influencia. [2026-11-05] [f.f. eff.] reescrito: qué produjo que este futuro no ocurriera.",
    "level": "documented",
    "conceptionYear": 1969,
    "closureYear": null,
    "presentEffect": {
      "text": "Never meant to be built, it worked as a critique, and the critique passed to a generation: critics regard Superstudio as an influence on Zaha Hadid, Rem Koolhaas and Bernard Tschumi, whose buildings were built.",
      "kind": "attributed",
      "source": "Wikipedia, \"Superstudio\" (citing Jonathan Ringen, 'Superstudio Pioneers of Conceptual Architecture').",
      "link": "https://en.wikipedia.org/wiki/Superstudio"
    },
