    "suffix": "",
    "name": "Cardiff Bay Opera House",
    "image": "/vstg/vstg-0040.webp",
    "description": "Zaha Hadid's design for the Cardiff Bay Opera House, which won an international competition held in the 1990s, intended as a permanent home for the Welsh National Opera.",
    "failedFuture": "A Welsh opera house meant to crown the Cardiff Bay redevelopment. The Millennium Commission rejected the lottery bid on 22 December 1995, judging the project financially risky, and the project then collapsed.",
    "source": "Wikipedia, \"Cardiff Bay Opera House\".",
    "link": "https://en.wikipedia.org/wiki/Cardiff_Bay_Opera_House",
    "license": "Image: \"Cardiff Bay WMC.jpg\", by grahamwell. CC BY-SA 2.0. Via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:Cardiff_Bay_WMC.jpg",
    "status": "Corregido: el diseño es de Zaha Hadid (no de Jørn Utzon). Pendiente: año de concepción (la fuente solo dice 'años noventa'), por lo que la distancia no se calcula. [2026-11-05] [f.f. eff.] reescrito: qué produjo que este futuro no ocurriera.",
    "level": "documented",
    "conceptionYear": null,
    "closureYear": 1995,
    "presentEffect": {
      "text": "Because the opera house was refused in 1995, the site went to the Wales Millennium Centre, opened in 2004, and the Welsh National Opera found its home there in a different building. Hadid would wait several more years for her first major buildings.",
      "kind": "documented",
      "source": "Wikipedia, \"Cardiff Bay Opera House\" and \"Wales Millennium Centre\".",
      "link": "https://en.wikipedia.org/wiki/Wales_Millennium_Centre"
    },
