    "image": "/vstg/vstg-0052.webp",
    "description": "Chile's economic decision-support system under Salvador Allende, designed by Stafford Beer: a telex network (Cybernet), statistical software (Cyberstride), an economic simulator (CHECO) and an operations room (Opsroom).",
    "failedFuture": "A planned economy steered in near real time, with factories linked by telex to a control room in Santiago. By May 1973 about 26.7% of nationalised industries, half of the sector's revenue, had been included to some degree; after the coup of 11 September 1973 the military abandoned it and destroyed the operations room.",
    "source": "Wikipedia, \"Project Cybersyn\".",
    "link": "https://en.wikipedia.org/wiki/Project_Cybersyn",
    "license": "Image: \"CyberSyn-render-103.png\", by Rama. CC BY-SA 3.0 fr. Via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:CyberSyn-render-103.png",
    "status": "Sustituto: efecto presente atribuido (The Guardian; Phillips y Rozworski 2019; Morozov 2014) vía Wikipedia; pendiente abrir los originales. [2026-11-05] [f.f. eff.] reescrito: qué produjo que este futuro no ocurriera.",
    "level": "documented",
    "conceptionYear": 1971,
    "closureYear": 1973,
    "presentEffect": {
      "text": "Because the coup ended it, Cybersyn never had to prove itself, and it returned decades later as a reference in debates on data and planning: The Guardian called it a socialist internet ahead of its time, and Evgeny Morozov (2014) linked it to big data and algorithmic monitoring.",
      "kind": "attributed",
      "source": "Wikipedia, \"Project Cybersyn\" (citing The Guardian; Phillips and Rozworski, 2019; Morozov, 2014).",
      "link": "https://en.wikipedia.org/wiki/Project_Cybersyn"
    },
