    "image": "/vstg/vstg-0053.webp",
    "description": "Study drawings and test models of a spacecraft driven by small nuclear explosions, developed at General Atomics between 1958 and 1965.",
    "failedFuture": "A ship pushed across the solar system by a series of nuclear explosions behind it; a 1959 NASA profile imagined a 125-day Mars round trip with eight astronauts. The Partial Test Ban Treaty of 1963 prohibited nuclear explosions in the atmosphere and in space and cut political support.",
    "source": "Dyson, G. (2002). Project Orion: The True Story of the Atomic Spaceship. Henry Holt and Company. Wikipedia, \"Project Orion (nuclear propulsion)\".",
    "link": "https://en.wikipedia.org/wiki/Project_Orion_(nuclear_propulsion)",
    "license": "Image: \"Model of proposed Orion Nuclear Pulse spacecraft.jpg\", by Joe Loong from Reston, USA. CC BY-SA 2.0. Via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:Model_of_proposed_Orion_Nuclear_Pulse_spacecraft.jpg",
    "status": "Efecto presente verificado en Wikipedia. La ficha da 1964 como año de cancelación; se mantiene 1965 de la ficha original (pendiente de confirmar). [2026-11-05] [f.f. eff.] reescrito: qué produjo que este futuro no ocurriera.",
    "level": "documented",
    "conceptionYear": 1958,
    "closureYear": 1965,
    "presentEffect": {
      "text": "Because the 1963 test ban made it impossible, nuclear pulse propulsion never flew, and spacecraft stayed chemical: the 125-day round trip to Mars it promised is still not possible. Its designs survive in studies such as Penn State's since 1998.",
      "kind": "documented",
      "source": "Wikipedia, \"Project Orion (nuclear propulsion)\".",
      "link": "https://en.wikipedia.org/wiki/Project_Orion_(nuclear_propulsion)"
    },
    "anchorYear": 2020,
    "distance": 62
