    "image": "/vstg/vstg-0125.webp",
    "description": "Ada Lovelace's notes on Babbage's Analytical Engine, published in September 1843 in Taylor's Scientific Memoirs. Note G contains a method for calculating Bernoulli numbers. The engine was never built.",
    "failedFuture": "A program for a machine that was never built, published in 1843. It was never tested, and it is often called the first published computer program.",
    "source": "Wikipedia, \"Ada Lovelace\".",
    "link": "https://en.wikipedia.org/wiki/Ada_Lovelace",
    "license": "Image: \"Ada Lovelace Chalon portrait.jpg\", by Alfred Edward Chalon. Public domain. Via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:Ada_Lovelace_Chalon_portrait.jpg",
