    "image": "/vstg/vstg-0128.webp",
    "description": "Ignaz Semmelweis introduced chlorinated hand washing in Vienna in 1847, after the maternity clinic's mortality from puerperal fever had reached ten percent or more. Mortality fell to about two percent. He died in a mental institution in 1865.",
    "failedFuture": "A method that would have saved mothers, rejected by many doctors of his time.",
    "source": "Bibliotheca Alexandrina, SCIplanet, \"Ignaz Semmelweis: Killed by Ignorance\".",
    "link": "https://www.bibalex.org/SCIplanet/en/Article/Details.aspx?id=7238",
    "license": "Image: \"Ignaz Semmelweis 1860.jpg\", by after Jenő Doby. Public domain. Via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:Ignaz_Semmelweis_1860.jpg",
    "status": "Efecto presente verificado en Wikipedia. [2026-11-05] [f.f. eff.] reescrito: qué produjo que este futuro no ocurriera.",
    "level": "documented",
    "conceptionYear": 1847,
    "closureYear": 1865,
    "presentEffect": {
      "text": "Because his method was rejected, mothers kept dying of childbed fever for decades, until germ theory explained his results. His name now describes the reflex of rejecting evidence that contradicts habit, and in 2020 he became the face of handwashing during the pandemic.",
      "kind": "documented",
      "source": "Wikipedia, \"Ignaz Semmelweis\".",
      "link": "https://en.wikipedia.org/wiki/Ignaz_Semmelweis"
    },
    "anchorYear": 2020,
    "distance": 173
