    "image": "/vstg/vstg-0161.webp",
    "description": "Filippo Tommaso Marinetti published the Manifesto of Futurism on 5 February 1909 in La gazzetta dell'Emilia. Le Figaro reprinted it on 20 February 1909.",
    "failedFuture": "A future built on speed, machines and the destruction of the old. The movement split in 1914 and tied itself to Fascism; organised Futurism ended with Marinetti's death in 1944.",
    "source": "Wikipedia, \"Futurism\".",
    "link": "https://en.wikipedia.org/wiki/Futurism",
    "license": "Image: Front page of Le Figaro, 20 February 1909, with the Futurist Manifesto. Source: smashingmagazine.com. Used in a non-profit academic archive; contact to credit or remove.",
    "status": "Efecto presente verificado en Wikipedia. [2026-11-05] [f.f. eff.] reescrito: qué produjo que este futuro no ocurriera.",
    "level": "documented",
    "conceptionYear": 1909,
    "closureYear": 1944,
    "presentEffect": {
      "text": "Because Futurism's future died with Fascism, it was long kept apart after 1945, and its full rehabilitation came late, with the Guggenheim's 2014 retrospective. Its traces are everyday: Boccioni's sculpture on the 20-cent coin and Futurist railway stations still in use.",
      "kind": "documented",
      "source": "Wikipedia, \"Futurism\".",
      "link": "https://en.wikipedia.org/wiki/Futurism"
    },
    "anchorYear": 2020,
    "distance": 111
