    "name": "Yañalif, the Latin alphabet for Soviet Turkic languages",
    "image": "/vstg/vstg-0166.webp",
    "description": "Yañalif, a Latin-based alphabet devised for Turkic languages, was adopted in Tatarstan in 1927; its final version came in 1928. It was used for Tatar and Bashkir and other Soviet languages.",
    "failedFuture": "Soviet Latinisation ended with a ban. The government prohibited Yañalif in 1939, and it remained in use until January 1940, when the switch to Cyrillic was complete. Learning two alphabets was considered problematic.",
    "source": "Wikipedia, \"Yañalif\".",
    "link": "https://en.wikipedia.org/wiki/Ya%C3%B1alif",
    "license": "Image: \"New Turkic Alphabet initiators.jpg\", by unknown author. Public domain. Via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:New_Turkic_Alphabet_initiators.jpg",
    "status": "Efecto presente verificado en Wikipedia. [2026-11-05] [f.f. eff.] reescrito: qué produjo que este futuro no ocurriera.",
    "level": "documented",
    "conceptionYear": 1927,
    "closureYear": 1940,
    "presentEffect": {
      "text": "Because Stalin replaced Latin with Cyrillic, Tatar is still written in Cyrillic: when Tatarstan tried to return to the Latin alphabet in 1999, a Russian federal law of 2002 required Cyrillic for the languages of the republics.",
      "kind": "documented",
      "source": "Wikipedia, \"Yañalif\".",
      "link": "https://en.wikipedia.org/wiki/Ya%C3%B1alif"
    },
    "anchorYear": 2020,
    "distance": 93
