    "description": "C. K. Ogden presented Basic English in his 1930 book Basic English: A General Introduction with Rules and Grammar. The core vocabulary is 850 words.",
    "failedFuture": "A reduced English meant to become an international auxiliary language and a teaching aid for English as a second language. It did not replace English in international use.",
