    "name": "Latinxua Sin Wenz, the Latin script for Chinese",
    "image": "/vstg/vstg-0170.webp",
    "description": "Latinxua Sin Wenz, a Latin-based script for Chinese, was established in 1931 through the work of Soviet sinologists and Moscow-based Chinese scholars, including Qu Qiubai. A prototype had been devised in 1929.",
    "failedFuture": "A plan to replace the characters with a Latin alphabet. Opposition grew; in 1944 the movement was officially curtailed in communist-controlled areas, and railway telegrams switched to Hanyu Pinyin in 1958.",
    "source": "Wikipedia, \"Latinxua Sin Wenz\".",
    "link": "https://en.wikipedia.org/wiki/Latinxua_Sin_Wenz",
    "license": "Image: Latinxua Koben, early textbook of Latinxua Sin Wenz. Source: zhuanlan.zhihu.com. Used in a non-profit academic archive; contact to credit or remove.",
    "status": "Efecto presente verificado en Wikipedia. Efecto modesto: la ficha no dice que Pinyin descienda formalmente de Sin Wenz. [2026-11-05] [f.f. eff.] reescrito: qué produjo que este futuro no ocurriera.",
    "level": "documented",
    "conceptionYear": 1931,
    "closureYear": 1944,
    "presentEffect": {
      "text": "Because the characters were not replaced, Chinese kept its script, and romanisation survived as a helper: Hanyu Pinyin (1958), similar to the Sin Wenz, is how Chinese is typed on phones and computers today.",
      "kind": "documented",
      "source": "Wikipedia, \"Latinxua Sin Wenz\".",
      "link": "https://en.wikipedia.org/wiki/Latinxua_Sin_Wenz"
    },
