    "failedFuture": "For decades no transmission was made in Lincos; it remained a theoretical exercise. In 1999 Yvan Dutil and Stéphane Dumas beamed a Lincos message from the Yevpatoria RT-70 radio telescope toward nearby stars, known as Cosmic Call; it was repeated in 2003.",
